return Object.entries($input.first().json).map(([journeyId, c]) => ({
  json: {
    journeyId, ...c,
    headers: {
      priority: "u=1, i",
      "sec-ch-ua": '"Not;A=Brand";v="8", "Chromium";v="150", "Brave";v="150"',
      "user-agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36"
    },
    subBody: {
      cruise: {
        journeyIdentifier: [journeyId]
      },
      productTypes: ["Cruise"],
      period: {
        start: {
          preOffset: 0,
          date: new Date().toISOString().slice(0, 10),
          postOffset: 999
        }
      },
      passengers: Object.entries({
        adults: 40,
        juveniles: 20,
        children: 10,
        babies: 1
      }).flatMap(([k, age]) => Array(c[k] || 0).fill(age)).map((age, idx) => ({ id: idx + 1, age }))
    }
  }
}));

const store = $getWorkflowStaticData('global');
store.prices ||= {};
const fmt = n => Number(n).toLocaleString('de-DE');
const union = (a, b) => [...new Set([...Object.keys(a || {}), ...Object.keys(b || {})])];
const out = [];
const cruises = $('Prepare Cruises').all();
for (let i = 0; i < cruises.length; i++) {
  const cfg = cruises[i].json;
  const detail = $('Cruise Detail').all()[i].json;
  if (!detail || !detail.title || detail.isCruiseAvailable === false) continue;
  const cur = detail.currency;
  const jid = cfg.journeyId;
  const catName = Object.fromEntries((detail.cabinItemsVariant || []).map(c => [c.cabinCode, c.cabinName]));
  const catOrder = Object.keys(catName);

  const spec = Object.fromEntries(($('Catalog').all()[i].json?.data?.kabinenkategorieSpezifikationList?.items || []).map(it => [it.cabin_category_code, { name: it.cabin_category_specification_name, cat: it.cabin_category.category_code }]));

  const subResp = $('SubCategory').all()[i].json;
  const variants = Object.fromEntries((subResp?.services || []).flatMap(s => (s.cruiseService?.cruiseVariants || []).map(v => [`${s.id}:${v.id}`, v.cabin])));
  const sub = {};
  for (const p of subResp?.products || []) {
    const ref = p.serviceReferences?.[0];
    const cabin = ref && variants[`${ref.serviceId}:${ref.serviceVariantId}`];
    if (!cabin) continue;
    const g = spec[cabin.cabinCode]?.cat || cabin.cabinCode[0];
    ((sub[g] ||= {})[cabin.tariffType] ||= { name: cabin.tariffName, rows: [] }).rows.push({ code: cabin.cabinCode, amount: p.priceInformation.amount });
  }

  const bl = {};
  const fb = {};
  for (const cab of detail.cabinItemsVariant || []) {
    const g = cab.cabinCode;
    for (const t of Object.values(cab).filter(v => v && typeof v === 'object' && Array.isArray(v.prices) && v.prices.length)) {
      const noFlight = t.prices.filter(p => p.flightIncluded === false);
      if (!noFlight.length) continue;
      (bl[g] ||= {})[t.tariffType] = noFlight[0].bookingLink;
      if (!sub[g]?.[t.tariffType]) (fb[g] ||= {})[t.tariffType] = { name: t.tariffName, amount: Math.min(...noFlight.map(p => p.amount)) };
    }
  }
  const link = (g, t, label) => bl[g]?.[t] ? `[${label}](https://aida.de/buchen${bl[g][t]})` : label;
  const tmin = (g, t) => sub[g]?.[t] ? Math.min(...sub[g][t].rows.map(r => r.amount)) : fb[g][t].amount;

  let body = `*${detail.title}*\n${(detail.itinerary || []).map(x => x.name).join(' – ')}\n${detail.startDate} bis ${detail.endDate} (${detail.duration} Tage)\n${cfg.adults}x Erwachsene, ${cfg.juveniles}x Jugendliche, ${cfg.children}x Kinder, ${cfg.babies}x Babys`;
  const seen = new Set();
  let changed = false;
  const track = (key, amt) => {
    const prev = store.prices[key];
    if (prev !== amt) changed = true;
    store.prices[key] = amt;
    seen.add(key);
    return prev != null && prev !== amt ? `${fmt(prev)} → ${fmt(amt)} ${cur}` : `${fmt(amt)} ${cur}`;
  };
  for (const g of union(sub, fb).sort((a, b) => catOrder.indexOf(a) - catOrder.indexOf(b))) {
    body += `\n\n*${catName[g] || g}*`;
    for (const t of union(fb[g], sub[g]).sort((a, b) => tmin(g, a) - tmin(g, b))) {
      const s = sub[g]?.[t];
      if (s) {
        body += `\n  ${link(g, t, s.name)}`;
        for (const r of s.rows.sort((a, b) => a.amount - b.amount))
          body += `\n    ${spec[r.code]?.name || r.code} (${r.code}): ${track(`${jid}|${t}|${r.code}`, r.amount)}`;
      } else {
        body += `\n  ${link(g, t, fb[g][t].name)}: ${track(`${jid}|${t}|#${g}`, fb[g][t].amount)}`;
      }
    }
  }
  for (const k of Object.keys(store.prices)) if (k.startsWith(`${jid}|`) && !seen.has(k)) { changed = true; delete store.prices[k]; }
  if (changed) {
    const chunks = [];
    let cur = '';
    for (const line of body.split('\n')) {
      if (cur && cur.length + line.length + 1 > 4000) { chunks.push(cur); cur = ''; }
      cur += (cur ? '\n' : '') + line;
    }
    if (cur) chunks.push(cur);
    for (const chatId of cfg.telegramChatIds) for (const chunk of chunks) out.push({ json: { chatId, message: chunk } });
  }
}
const active = new Set(cruises.map(c => c.json.journeyId));
for (const k of Object.keys(store.prices)) if (!active.has(k.split('|')[0])) delete store.prices[k];
return out;
